services.AddZeroObservability();

// Nothing else. Every request through ISender is now logged, traced and timed.
// Subscribe from the host:
//   tracing.AddSource(ZeroTelemetry.ActivitySourceName)
//   metrics.AddMeter(ZeroTelemetry.MeterName)

// A validation failure is a normal answer, not a fault, so it does not log as one.
// A handler stays free of all three:
public sealed class CloseInvoiceHandler(IInvoiceStore store) : ICommandHandler<CloseInvoice>
{
    public async Task<Result<Unit>> HandleAsync(CloseInvoice command, CancellationToken cancellationToken)
    {
        var invoice = await store.FindAsync(command.Id, cancellationToken);

        return invoice is null
            ? Error.NotFound("invoice.missing", $"No invoice {command.Id}.")
            : Unit.Success;
    }
}
